SELECT event, distinct_id, timestamp, properties.event_id, properties.occurred_at, properties.anonymous_id, properties.session_id, properties.session_sequence, properties.scenario_id, properties.checkout_id, properties.order_id, properties.items, properties.value_minor, properties.schema_version, properties.environment, properties.activity_origin, properties.catalog_origin, properties.display_provenance, properties.simulation, properties.currency, properties.consent_state, properties.app_version, properties.catalog_version, properties.device_class FROM events WHERE timestamp >= now() - INTERVAL 1 HOUR AND properties.test_run_id = 'commerce-live-1793727480072' ORDER BY properties.scenario_id, properties.session_sequence LIMIT 100
